style.css:
@-moz-document domain("web.whatsapp.com") {
/* Global Backgrounds, App Shell, Main Chat & Left Bar */
    html, body, #app, .app-wrapper-web, #main, #pane-side,
    div[tabindex="-1"], div[role="region"],
    ._a72d, ._a83v, ._a99v {
        background-color: #FF0000 !important;
    }

    /* Far Left Vertical Navigation Bar */
    header[role="navigation"], 
    header[role="navigation"] > div,
    nav, 
    nav > div {
        background-color: #FF0000 !important;
        border-right: 1px solid #FF0000 !important;
    }

    /* Search Bar Container & Input Field */
    div[role="search"],
    div[role="search"] > div,
    ._ai08, ._ai07, ._ai06,
    input[type="text"] {
        background-color: #FF0000 !important;
        color: #FFFFFF !important;
    }

    /* Chat List Cards & Hover States */
    #pane-side div[role="gridcell"],
    #pane-side div[role="row"],
    div[data-testid="cell-frame-container"] {
        background-color: #FF0000 !important;
        border-bottom: 1px solid #FF0000 !important;
    }

    /* Header Bars (Chat Header & Sidebar Header) */
    header, #main header, #pane-side header {
        background-color: #FF0000 !important;
        border-bottom: 1px solid #FF0000 !important;
    }

    /* Message Bubbles (Sent & Received) */
    div[data-id] .message-out .aria-container,
    div[data-id] .message-out > div,
    div[data-id] .message-in .aria-container,
    div[data-id] .message-in > div {
        background-color: #FF0000 !important;
    }

    /* Quoted / Reply Preview Blocks Inside Messages */
    div[data-id] div[role="button"],
    ._ak8j, ._ak8k, ._ak8l {
        background-color: #FF0000 !important;
    }

    /* Bottom Message Input Bar & Footer Banner */
    footer, #main footer, 
    footer > div,
    div[data-testid="chat-footer"],
    ._a82v, ._a82w {
        background-color: #FF0000 !important;
        border-top: 1px solid #FF0000 !important;
    }
}
